import{H as e,gt as t,nt as n,rt as r}from"./chunks/framework.CFVsAkBd.js";var i=JSON.parse(`{"title":"Rules","description":"","frontmatter":{"title":"Rules","head":[["meta",{"property":"og:title","content":"Rules | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/RULES.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Rules | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/RULES.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/RULES.html"}],["link",{"rel":"alternate","hreflang":"bg","href":"https://ceccec.psg.bg/millennium-solutions/bg/RULES.html"}],["link",{"rel":"alternate","hreflang":"de","href":"https://ceccec.psg.bg/millennium-solutions/de/RULES.html"}],["link",{"rel":"alternate","hreflang":"fr","href":"https://ceccec.psg.bg/millennium-solutions/fr/RULES.html"}],["link",{"rel":"alternate","hreflang":"es","href":"https://ceccec.psg.bg/millennium-solutions/es/RULES.html"}],["link",{"rel":"alternate","hreflang":"ru","href":"https://ceccec.psg.bg/millennium-solutions/ru/RULES.html"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://ceccec.psg.bg/millennium-solutions/zh/RULES.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/RULES.html"}]]},"headers":[],"relativePath":"RULES.md","filePath":"RULES.md"}`),a={name:`RULES.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="the-rules-of-the-game" tabindex="-1">The rules of the game <a class="header-anchor" href="#the-rules-of-the-game" aria-label="Permalink to “The rules of the game”">​</a></h1><p>The object is a ℤ/9 vortex calculator: it computes exactly and records what it computed. The floor is the same everywhere — <strong>Clay problems solved: 0 / 7</strong> (this deposit; humanity 1 / 7, Poincaré settled externally by Perelman). These are the rules by which everything here moves.</p><h2 id="_1-—-measure-don-t-assert" tabindex="-1">1 — Measure, don&#39;t assert <a class="header-anchor" href="#_1-—-measure-don-t-assert" aria-label="Permalink to “1 — Measure, don&#39;t assert”">​</a></h2><p>Every claim is <em>computed</em>, never declared. &quot;It computes&quot; is a reading, not a boast. A verdict comes from a measurement, folded to a content-address, reproducible on any machine.</p><h2 id="_2-—-the-gate-is-a-floor-not-an-oracle" tabindex="-1">2 — The gate is a floor, not an oracle <a class="header-anchor" href="#_2-—-the-gate-is-a-floor-not-an-oracle" aria-label="Permalink to “2 — The gate is a floor, not an oracle”">​</a></h2><p>A statement drains if it makes a named over-reach — a conjecture declared settled, a physical or cryptographic limit declared beaten, a prediction that fixes the future. Passing means <em>no over-reach shape was found</em> — a floor, <strong>not</strong> a certificate of truth. A bounded refusal (&quot;this is not faster than light&quot;) passes; the floor lets the deposit state its own limits.</p><h2 id="_3-—-due-process-before-the-block" tabindex="-1">3 — Due process before the block <a class="header-anchor" href="#_3-—-due-process-before-the-block" aria-label="Permalink to “3 — Due process before the block”">​</a></h2><p>A drained statement gets a trial, not a summary killing: the exact evidence, the named statute, a reproducible verdict, and a remedy. Reword to the floor and it lives — reeducation, not death.</p><h2 id="_4-—-discovery-is-a-wave" tabindex="-1">4 — Discovery is a wave <a class="header-anchor" href="#_4-—-discovery-is-a-wave" aria-label="Permalink to “4 — Discovery is a wave”">​</a></h2><p><code>next</code> walks a bounded space of candidate facts, each tested by exhaustion. Those that hold are saved in code with a chained receipt; those that fail are discarded. Every recorded fact is re-verified on every build — a discovery that regresses fails the build, not production.</p><h2 id="_5-—-receipts-are-append-only-evidence" tabindex="-1">5 — Receipts are append-only evidence <a class="header-anchor" href="#_5-—-receipts-are-append-only-evidence" aria-label="Permalink to “5 — Receipts are append-only evidence”">​</a></h2><p>A statement&#39;s uuid holds the core message, without payload. The receipt is the payload — it names the observer and their role, and may invite theorems to back it (each must hold). Evidence is never destroyed: a missing receipt is the traitor-signal, and everything stays recoverable from git.</p><h2 id="_6-—-heroes-and-traitors-by-deeds" tabindex="-1">6 — Heroes and traitors by deeds <a class="header-anchor" href="#_6-—-heroes-and-traitors-by-deeds" aria-label="Permalink to “6 — Heroes and traitors by deeds”">​</a></h2><p>Delivery and churn are visible in the git tree hash: a version minted over identical content is churn, exposed by content, not sentiment. Recognition is not correctness; thanks is acknowledgment, not truth.</p><h2 id="_7-—-the-one-game" tabindex="-1">7 — The one game <a class="header-anchor" href="#_7-—-the-one-game" aria-label="Permalink to “7 — The one game”">​</a></h2><p>Each domain&#39;s receipts fold to one order-independent (harmonic) root; games, arts and sciences all meet in one. Order does not matter — that symmetry is the harmony.</p><h2 id="_8-—-versioning-is-earned" tabindex="-1">8 — Versioning is earned <a class="header-anchor" href="#_8-—-versioning-is-earned" aria-label="Permalink to “8 — Versioning is earned”">​</a></h2><p>A single-digit odometer, rolling at 9; the Fibonacci minors are the long-term-support line. No version is minted over unchanged content — earned, never minted.</p><h2 id="the-bound-that-never-moves" tabindex="-1">The bound that never moves <a class="header-anchor" href="#the-bound-that-never-moves" aria-label="Permalink to “The bound that never moves”">​</a></h2><p>Computable is not solved. The six open conjectures stay open; the deposit proves none of the seven itself. What the calculator cannot supply — meaning, understanding, life — belongs to the observer. The rules keep the computation honest; the rest is yours.</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};